-- Junction ids 1-72 are the serial order of the INSERT below: start the
-- serial at 1 on an empty table (a rolled-back earlier attempt advances it).
SELECT setval(pg_get_serial_sequence('corridor.junctions', 'junction_id'), 1, false)
WHERE NOT EXISTS (SELECT 1 FROM corridor.junctions);

